use super::*;

/// Helper: wraps an expression with ExportString[..., "SVG"], evaluates it,
/// and returns the SVG string. Panics if evaluation fails or if the result
/// doesn't look like an SVG.
fn export_svg(expr: &str) -> String {
  let code = format!("ExportString[{}, \"SVG\"]", expr);
  let svg = interpret(&code).unwrap();
  // The exporter embeds the fonts an SVG uses as an @font-face <style> block
  // (see `embed_used_fonts`). Strip it here so these snapshots stay focused on
  // the graphics geometry instead of a base64-encoded font payload; font
  // embedding itself is covered by dedicated tests in the interpreter_tests
  // module.
  let svg = strip_font_style(&svg);
  assert!(
    svg.starts_with("<svg"),
    "Expected SVG output for {expr}, got: {}",
    &svg[..100.min(svg.len())]
  );
  assert!(svg.contains("</svg>"), "SVG should be complete for {expr}");
  svg
}

/// The y-axis tick labels of a rendered plot, top to bottom. Plotters draws
/// an empty `<text>` for every minor tick, so only the labelled ones are kept.
fn y_tick_labels(svg: &str) -> Vec<String> {
  let mut labels: Vec<(i64, String)> = svg
    .split("<text ")
    .skip(1)
    .filter_map(|tag| tag.split_once('>'))
    .filter(|(open, _)| open.contains("text-anchor=\"end\""))
    .filter_map(|(open, rest)| {
      let y = open.split("y=\"").nth(1)?.split('"').next()?;
      let text = rest.split('<').next()?.trim().to_string();
      Some((y.parse::<f64>().ok()? as i64, text))
    })
    .filter(|(_, text)| !text.is_empty())
    .collect();
  labels.sort_by_key(|(y, _)| *y);
  labels.into_iter().map(|(_, text)| text).collect()
}

/// Remove the embedded-font `<defs><style>…</style></defs>` block the exporter
/// injects right after the opening `<svg>` tag, leaving the rest untouched.
fn strip_font_style(svg: &str) -> String {
  const OPEN: &str = "\n<defs><style type=\"text/css\">";
  const CLOSE: &str = "</style></defs>";
  if let Some(start) = svg.find(OPEN)
    && let Some(rel) = svg[start..].find(CLOSE)
  {
    let end = start + rel + CLOSE.len();
    let mut out = String::with_capacity(svg.len());
    out.push_str(&svg[..start]);
    out.push_str(&svg[end..]);
    return out;
  }
  svg.to_string()
}

