    #[test]
    fn circle_arc_renders_open_path_not_full_ellipse() {
      // Regression: `Circle[c, r, {t1, t2}]` draws only the arc over that
      // angular range (an open one-sided curve), not a full circle. Previously
      // the angle range was ignored and a whole ellipse was emitted — the
      // Yin-Yang demonstration's inner curves showed a full border.
      let svg = export_svg("Graphics[{Circle[{0, 0}, 1, {Pi/2, 3 Pi/2}]}]");
      assert!(
        svg.contains("<path") && svg.contains(" A "),
        "partial Circle should emit an arc path, got:\n{svg}"
      );
      assert!(
        !svg.contains("<ellipse"),
        "partial Circle must not emit a full ellipse:\n{svg}"
      );
      // A full-turn range still draws the whole circle as an ellipse.
      let full = export_svg("Graphics[{Circle[{0, 0}, 1, {0, 2 Pi}]}]");
      assert!(full.contains("<ellipse"), "full Circle: {full}");
    }

