    #[test]
    fn graphics_primitives_are_symbolic() {
      assert_eq!(interpret("Circle[]").unwrap(), "Circle[{0, 0}]");
      assert_eq!(interpret("Disk[{1, 0}]").unwrap(), "Disk[{1, 0}]");
      assert_eq!(interpret("Point[{0, 0}]").unwrap(), "Point[{0, 0}]");
      assert_eq!(interpret("RGBColor[1, 0, 0]").unwrap(), "RGBColor[1, 0, 0]");
      assert_eq!(
        interpret("Offset[{10, 20}, {0, 0}]").unwrap(),
        "Offset[{10, 20}, {0, 0}]"
      );
      assert_eq!(interpret("Offset[{10, 20}]").unwrap(), "Offset[{10, 20}]");
      assert_eq!(interpret("GridLinesStyle").unwrap(), "GridLinesStyle");
      assert_eq!(interpret("LabelStyle").unwrap(), "LabelStyle");
      assert_eq!(interpret("Smaller").unwrap(), "Smaller");
      assert_eq!(interpret("Larger").unwrap(), "Larger");
      assert_eq!(
        interpret("RowBox[{\"a\", \"+\", \"b\"}]").unwrap(),
        "RowBox[{a, +, b}]"
      );
      // wolframscript prints `Graph[<n>, <m>]` (vertex count, edge count)
      // instead of the `-Graphics-` placeholder used for ad-hoc Graphics.
      // {1->2, 2->3} has three vertices {1, 2, 3} and two edges.
      assert_eq!(
        interpret("Graph[{1 -> 2, 2 -> 3}]").unwrap(),
        "Graph[<3>, <2>]"
      );
    }

