  mod export {
    use super::*;

    #[test]
    fn export_svg() {
      let path = temp_file("woxi_test_plot3d.svg");
      let result = interpret(&format!(
        "Export[\"{path}\", Plot3D[x + y, {{x, -1, 1}}, {{y, -1, 1}}]]"
      ));
      assert!(result.is_ok());
      let content = std::fs::read_to_string(&path).unwrap();
      assert!(content.starts_with("<svg"));
      assert!(content.contains("<polygon"));
      std::fs::remove_file(&path).ok();
    }

    /// Regression test: Export["foo.png", Plot[...]] used to write the raw
    /// SVG bytes to a file with a .png extension. It must now emit a real
    /// PNG whose rasterized content includes the tick labels (previously
    /// dropped because "sans-serif" had no matching font in the db).
    #[test]
    fn export_png_from_plot() {
      let path = temp_file("woxi_test_plot_export.png");
      let result = interpret(&format!(
        "Export[\"{path}\", Plot[Sin[x], {{x, -2 Pi, 2 Pi}}]]"
      ));
      assert!(result.is_ok(), "Export returned error: {result:?}");
      let bytes = std::fs::read(&path).unwrap();
      // PNG magic: 89 50 4E 47 0D 0A 1A 0A
      assert_eq!(
        &bytes[..8],
        &[0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A],
        "file at {path} is not a PNG"
      );
      // Decode and confirm the rasterized image is not uniformly white — if
      // text were dropped and the axis were the only dark element, there
      // would still be *some* non-white pixels, but we specifically want to
      // catch the regression where the sans-serif tick labels vanished.
      // As a proxy, count dark pixels in the left margin strip where the
      // y-axis tick labels live.
      let img = ::image::load_from_memory(&bytes).unwrap().to_luma8();
      let (w, h) = (img.width(), img.height());
      // Left 15% of the image — the y-axis label gutter. No axis lines or
      // plot curve touch this strip, so any non-white pixel must come from
      // a rendered tick label glyph.
      let gutter_w = (w as f32 * 0.15) as u32;
      let mut inked_pixels = 0u32;
      for y in 0..h {
        for x in 0..gutter_w {
          if img.get_pixel(x, y).0[0] < 240 {
            inked_pixels += 1;
          }
        }
      }
      // Threshold is a proxy for "the sans-serif tick labels rendered at all"
      // (the original regression dropped them entirely → ~0 inked pixels).
      // Kept comfortably below the count produced by the current tick-label
      // font so it still fires if the glyphs vanish.
      assert!(
        inked_pixels > 20,
        "y-axis tick labels appear to be missing: only {inked_pixels} \
         non-white pixels in the left gutter"
      );
      std::fs::remove_file(&path).ok();
    }

    /// Regression: Export[..., png, ImageResolution -> n] should scale
    /// the rasterized output to n DPI (vs the default 96 DPI). A Plot
    /// with ImageSize -> 800 at 300 DPI should come out at 2500 px wide.
    #[test]
    fn export_png_with_image_resolution() {
      let path_hi = temp_file("woxi_test_plot_export_hi.png");
      let path_lo = temp_file("woxi_test_plot_export_lo.png");
      let result_hi = interpret(&format!(
        "Export[\"{path_hi}\", \
         Plot[Sin[x], {{x, -3 Pi, 3 Pi}}, ImageSize -> 800], \
         ImageResolution -> 300]"
      ));
      assert!(result_hi.is_ok(), "Export returned error: {result_hi:?}");
      let result_lo = interpret(&format!(
        "Export[\"{path_lo}\", \
         Plot[Sin[x], {{x, -3 Pi, 3 Pi}}, ImageSize -> 800]]"
      ));
      assert!(result_lo.is_ok(), "Export returned error: {result_lo:?}");

      let bytes_hi = std::fs::read(&path_hi).unwrap();
      let bytes_lo = std::fs::read(&path_lo).unwrap();
      // PNG magic
      assert_eq!(
        &bytes_hi[..8],
        &[0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]
      );

      let img_hi = ::image::load_from_memory(&bytes_hi).unwrap();
      let img_lo = ::image::load_from_memory(&bytes_lo).unwrap();
      // 300 DPI / 96 DPI == 3.125×; 800 * 3.125 == 2500
      assert_eq!(img_hi.width(), 2500);
      assert_eq!(img_lo.width(), 800);
      // Height scales proportionally
      assert!(img_hi.height() > img_lo.height() * 3);

      std::fs::remove_file(&path_hi).ok();
      std::fs::remove_file(&path_lo).ok();
    }

    #[test]
    fn export_jpeg_from_plot() {
      let path = temp_file("woxi_test_plot_export.jpg");
      let result =
        interpret(&format!("Export[\"{path}\", Plot[Cos[x], {{x, 0, 2 Pi}}]]"));
      assert!(result.is_ok(), "Export returned error: {result:?}");
      let bytes = std::fs::read(&path).unwrap();
      // JPEG SOI marker: FF D8 FF
      assert_eq!(
        &bytes[..3],
        &[0xFF, 0xD8, 0xFF],
        "file at {path} is not a JPEG"
      );
      std::fs::remove_file(&path).ok();
    }

    #[test]
    fn export_jpeg_from_image_numericarray() {
      // The audit's Export case: write a NumericArray-backed RGB image
      // to a JPEG file, get back the filename. Previously the audit
      // harness hit ARG_MAX before the image could even reach Export;
      // pin the behaviour here from a Rust test so the full path is
      // exercised.
      let path = temp_file("woxi_test_export_image_numericarray.jpg");
      let _ = std::fs::remove_file(&path);
      let code = format!(
        "Export[\"{path}\", Image[NumericArray[\
         {{{{{{62, 91, 147}}, {{69, 99, 160}}, {{74, 106, 167}}}}, \
         {{{{77, 111, 172}}, {{80, 114, 175}}, {{81, 115, 175}}}}, \
         {{{{80, 115, 173}}, {{81, 115, 173}}, {{81, 114, 173}}}}}}, \
         \"UnsignedInteger8\"]]]"
      );
      let result = interpret(&code).unwrap();
      assert_eq!(result, path);
      let bytes = std::fs::read(&path).unwrap();
      assert_eq!(
        &bytes[..3],
        &[0xFF, 0xD8, 0xFF],
        "file at {path} is not a JPEG"
      );
      std::fs::remove_file(&path).ok();
    }

    /// Regression: `Export["foo.gif", Table[graphics, …]]` must produce
    /// a multi-frame animated GIF. Previously the list of graphics fell
    /// through to the text rasterizer and produced a tiny single-frame
    /// GIF (1504×15 px) of the textual list representation.
    #[test]
    fn export_animated_gif_from_graphics_list() {
      let path = temp_file("woxi_test_animated.gif");
      let result = interpret(&format!(
        "Export[\"{path}\", \
         Table[Graphics[{{Disk[{{0, 0}}, r/10]}}, \
                        PlotRange -> {{{{-1, 1}}, {{-1, 1}}}}], \
               {{r, 1, 5}}]]"
      ));
      assert!(result.is_ok(), "Export returned error: {result:?}");

      let bytes = std::fs::read(&path).unwrap();
      // GIF magic: "GIF89a"
      assert_eq!(&bytes[..6], b"GIF89a", "file at {path} is not a GIF");

      // Decode and verify it's actually multi-frame.
      let file = std::io::BufReader::new(std::fs::File::open(&path).unwrap());
      let decoder = ::image::codecs::gif::GifDecoder::new(file).unwrap();
      use ::image::AnimationDecoder;
      let frames: Vec<_> = decoder
        .into_frames()
        .collect::<Result<Vec<_>, _>>()
        .unwrap();
      assert_eq!(frames.len(), 5, "expected 5 frames, got {}", frames.len());

      // Sanity: dimensions are not the broken 1504×15 from the regression.
      let (w, h) = frames[0].buffer().dimensions();
      assert!(
        w >= 100 && h >= 100,
        "frame dimensions {w}×{h} look like the text-rasterizer regression"
      );

      std::fs::remove_file(&path).ok();
    }
  }

