    // Regression: ListPlot used to silently drop Around[...] values,
    // rendering an empty plot. Around data must plot the central values
    // with error bars covering the uncertainty interval.
    #[test]
    fn list_plot_around_y_values() {
      let svg = export_svg(
        "ListPlot[{Around[2.19, 1.18], Around[3.27, 1.07], \
         Around[3.61, 0.74], Around[5.88, 0.56]}]",
      );
      // All 4 points must be plotted as markers ...
      assert_eq!(svg.matches("<circle").count(), 4);
      // ... each with a vertical error bar plus two caps in the series
      // color (12 segments beyond the axes/tick strokes).
      assert_eq!(svg.matches("stroke=\"#5E81B5\"").count(), 12);
    }

