    // IntervalMarkers -> "Bands" replaces the error bars with one filled
    // band per series covering the uncertainty intervals.
    #[test]
    fn list_plot_around_interval_markers_bands() {
      let svg = export_svg(
        "ListPlot[{Around[2.19, 1.18], Around[3.27, 1.07], \
         Around[3.61, 0.74], Around[5.88, 0.56]}, \
         IntervalMarkers -> \"Bands\"]",
      );
      assert_eq!(svg.matches("<circle").count(), 4);
      // A translucent filled band in the series color ...
      assert_eq!(
        svg
          .matches("<polygon opacity=\"0.2\" fill=\"#5E81B5\"")
          .count(),
        1
      );
      // ... with a single outline stroke instead of the 12 bar segments.
      assert_eq!(svg.matches("stroke=\"#5E81B5\"").count(), 1);
    }

