    #[test]
    fn bar_chart_plot_label_box_syntax() {
      // PlotLabel strings with inline linear box syntax
      // (\!\(\*SuperscriptBox[...]\)) must render as sub/superscript
      // tspans, not as the raw escape sequences.
      let svg = export_svg(
        r#"BarChart[{1, 7, 9, 2},
             PlotLabel -> "hMgamgam: M(\!\(\*SuperscriptBox[\(\[Pi]\), \(-\)]\)\!\(\*SuperscriptBox[\(\[Pi]\), \(0\)]\))",
             Frame -> True, FrameLabel -> {"bin", "counts"}, ImageSize -> 600]"#,
      );
      assert!(
        !svg.contains("SuperscriptBox"),
        "raw box syntax leaked into SVG: {svg}"
      );
      assert!(
        svg.contains(
          "π<tspan baseline-shift=\"super\" font-size=\"70%\">-</tspan>"
        ) && svg.contains(
          "π<tspan baseline-shift=\"super\" font-size=\"70%\">0</tspan>"
        ),
        "PlotLabel superscripts not rendered: {svg}"
      );
    }

    #[test]
    fn bar_chart_horizontal_plot_label_box_syntax() {
      // Same via the horizontal (BarOrigin -> Left) generator.
      let svg = export_svg(
        r#"BarChart[{1, 2}, BarOrigin -> Left,
             PlotLabel -> "M(\!\(\*SuperscriptBox[\(\[Pi]\), \(-\)]\))"]"#,
      );
      assert!(
        !svg.contains("SuperscriptBox"),
        "raw box syntax leaked into SVG: {svg}"
      );
      assert!(
        svg.contains(
          "π<tspan baseline-shift=\"super\" font-size=\"70%\">-</tspan>"
        ),
        "PlotLabel superscript not rendered: {svg}"
      );
    }

