    #[test]
    fn histogram_grouped_datasets() {
      // Regression: a list of lists used to render an empty SVG. Each sublist
      // is now drawn as its own overlaid histogram.
      let empty = "<svg xmlns=\"http://www.w3.org/2000/svg\"></svg>";
      let svg = export_svg(
        "Histogram[{{1, 2, 2, 3}, {5, 6, 6, 7}, {9, 10, 10, 11}}, {1}]",
      );
      assert_ne!(svg, empty, "grouped histogram must not be empty");
      // Three datasets over disjoint unit-width ranges → many bars, and each
      // dataset uses a distinct default plot color.
      assert!(svg.matches("<rect").count() > 3, "expected multiple bars");
    }

    #[test]
    fn histogram_pdf_height_spec() {
      // The "PDF" height spec normalizes bar heights to a probability
      // density (total area 1), so the tallest bar is well below the raw
      // count. The rendered y-axis therefore shows fractional tick labels.
      let svg = export_svg(r#"Histogram[{1, 1, 1, 1, 2, 2, 3}, {1}, "PDF"]"#);
      let empty = "<svg xmlns=\"http://www.w3.org/2000/svg\"></svg>";
      assert_ne!(svg, empty, "PDF histogram must render");
      // A raw-count histogram of the same data would label the y-axis with
      // integer counts up to 4; the PDF version stays below 1. Only the y
      // labels (`text-anchor="end"`) say anything about the heights — the x
      // axis runs over the bin edges, 4 among them.
      let y_labels: Vec<&str> = svg
        .split("text-anchor=\"end\"")
        .skip(1)
        .filter_map(|s| s.split_once('>'))
        .filter_map(|(_, rest)| rest.split_once('<'))
        .map(|(text, _)| text.trim())
        .filter(|text| !text.is_empty())
        .collect();
      assert!(
        !y_labels.contains(&"4"),
        "PDF heights should not reach the raw count of 4: {y_labels:?}"
      );
    }

