    /// `ContourPlot[lhs == rhs, …]` draws the equation's implicit curve
    /// (the zero contour of `lhs - rhs`) instead of an empty plot.
    #[test]
    fn contour_plot_equation_draws_curve() {
      let svg =
        export_svg("ContourPlot[x^2 + y^2 == 4, {x, -2, 2}, {y, -2, 2}]");
      assert!(
        svg.contains("<polyline"),
        "expected the implicit circle as contour polylines, got: {}",
        &svg[..svg.len().min(200)]
      );
    }

    /// `ContourStyle` colours and thickens the contour lines. Both the
    /// function form and the equation form draw through it — the equation
    /// form is how a Demonstration draws a stability boundary.
    #[test]
    fn contour_plot_honors_contour_style() {
      for expr in [
        "ContourPlot[x + y, {x, 0, 4}, {y, 0, 4}, ContourShading -> False, \
         ContourStyle -> {Thick, Blue}]",
        "ContourPlot[y == x, {x, 0, 4}, {y, 0, 4}, \
         ContourStyle -> {Thick, Blue}]",
      ] {
        let svg = export_svg(expr);
        assert!(
          svg.contains("stroke=\"rgb(0,0,255)\""),
          "ContourStyle colour missing from {expr}"
        );
        // `Thick` is 2 display pixels; the default contour line is thinner
        // than one, so the styled stroke must be clearly wider.
        let widths: Vec<f64> = svg
          .split("stroke-width=\"")
          .skip(1)
          .filter_map(|s| s.split('"').next()?.parse().ok())
          .collect();
        assert!(
          widths.iter().any(|w| *w >= 19.0),
          "expected a Thick contour stroke in {expr}, widths: {widths:?}"
        );
      }
    }

    /// The default contour line keeps its thin dark-grey look when no
    /// `ContourStyle` is given.
    #[test]
    fn contour_plot_default_line_style_unchanged() {
      let svg = export_svg("ContourPlot[y == x, {x, 0, 4}, {y, 0, 4}]");
      assert!(
        svg.contains("stroke=\"#404040\" stroke-width=\"9.0\""),
        "default contour stroke changed"
      );
    }

    /// `FrameLabel` and `Epilog` reach a contour plot the same way they
    /// reach a function plot: the labels sit outside the frame and the
    /// epilog primitives are drawn over the curves in data coordinates.
    #[test]
    fn contour_plot_honors_frame_label_and_epilog() {
      let svg = export_svg(
        "ContourPlot[y == x, {x, 0, 4}, {y, 0, 4}, \
         FrameLabel -> {\"across\", \"up\"}, \
         Epilog -> {Text[\"here\", {2, 3}], Red, PointSize[0.05], \
         Point[{1, 1}]}]",
      );
      for text in [">across</text>", ">up</text>", ">here</text>"] {
        assert!(svg.contains(text), "missing {text} in:\n{svg}");
      }
      assert!(
        svg.contains("<circle") && svg.contains("rgb(255,0,0)"),
        "expected the red Epilog point"
      );
    }

    /// A `DensityPlot` takes the same labels and epilog — the option
    /// parsing is shared across the whole density/contour family.
    #[test]
    fn density_plot_honors_frame_label_and_epilog() {
      let svg = export_svg(
        "DensityPlot[x + y, {x, 0, 4}, {y, 0, 4}, \
         FrameLabel -> {\"across\", \"up\"}, Epilog -> {Text[\"here\", {2, 3}]}]",
      );
      for text in [">across</text>", ">up</text>", ">here</text>"] {
        assert!(svg.contains(text), "missing {text} in a DensityPlot");
      }
    }

    /// `ImageSize -> n {1, 1}` — a plot holds its arguments, so the option
    /// value arrives unevaluated and has to be evaluated before it can be
    /// read as the square size it describes.
    #[test]
    fn image_size_product_gives_a_square_picture() {
      for expr in [
        "Plot[Sin[x], {x, 0, 4}, ImageSize -> 400 {1, 1}]",
        "ContourPlot[y == x, {x, 0, 4}, {y, 0, 4}, ImageSize -> 400 {1, 1}]",
      ] {
        let svg = export_svg(expr);
        assert!(
          svg.starts_with("<svg width=\"400\" height=\"400\""),
          "expected a 400x400 picture for {expr}, got: {}",
          &svg[..svg.len().min(80)]
        );
      }
    }

    /// A pre-rendered equation ContourPlot must merge with other graphics
    /// inside Show — the curve is carried along as plot-source line series.
    #[test]
    fn show_merges_equation_contour_plot_with_graphics() {
      let svg = export_svg(
        "Show[{ContourPlot[y^2 == 20 x, {x, -20, 20}, {y, -20, 20}], \
         Graphics[Point[{5, 0}]]}, PlotRange -> All]",
      );
      assert!(
        svg.contains("<polyline"),
        "expected the parabola curve inside Show"
      );
      assert!(
        svg.contains("<circle"),
        "expected the merged Point inside Show"
      );
    }

    /// Show must splice a *list* of Graphics (e.g. a collected list of
    /// per-ray line graphics) instead of silently dropping it.
    #[test]
    fn show_flattens_nested_graphics_lists() {
      let svg = export_svg(
        "Show[{Graphics[Point[{5, 0}]], \
         {Graphics[Line[{{0, 0}, {10, 10}}]], \
          Graphics[Line[{{0, 0}, {10, -10}}]]}}, PlotRange -> All]",
      );
      let lines = svg.matches("<polyline").count();
      assert_eq!(
        lines, 2,
        "expected both nested-list Lines to merge, got {lines}"
      );
      assert!(svg.contains("<circle"), "expected the Point to survive");
    }

    #[test]
    fn region_plot_basic() {
      insta::assert_snapshot!(export_svg(
        "RegionPlot[x^2 + y^2 < 1, {x, -2, 2}, {y, -2, 2}]"
      ));
    }

    /// A `Plus` term with a negative coefficient joins with `-` and drops the
    /// sign, so a polynomial label reads `-5 - 5 x - 5 x^2`, not
    /// `-5 + -5 x + -5 x^2`. Wolfram's boxes join the same way.
    #[test]
    fn negative_coefficients_join_with_a_minus() {
      let label = |expr: &str| -> String {
        let svg = export_svg(&format!(
          "RegionPlot[y > x, {{x, -2, 2}}, {{y, -2, 2}}, PlotLabel -> {expr}]"
        ));
        svg
          .split("fill=\"#333\">")
          .nth(1)
          .and_then(|t| t.split("</text>").next())
          .unwrap_or_default()
          .to_string()
      };
      assert_eq!(label("-5 x - 5"), "-5 - 5 x");
      assert_eq!(label("a - 2.5 b"), "a - 2.5 b");
      assert_eq!(label("a - b"), "a - b");
      // A positive term still joins with `+`.
      assert_eq!(label("a + 3 b"), "a + 3 b");
    }

    /// The plotting heads hold their arguments, so a body that names part of
    /// itself indirectly (`p = …; RegionPlot[y > p, …]`) arrives unevaluated
    /// and substituting the plot variables into it finds nothing to replace.
    /// Regression: the region came out empty.
    #[test]
    fn field_plot_body_named_indirectly_is_resolved() {
      let direct =
        export_svg("RegionPlot[y > x^2 - 1, {x, -2, 2}, {y, -2, 2}]");
      let indirect =
        export_svg("p = x^2 - 1; RegionPlot[y > p, {x, -2, 2}, {y, -2, 2}]");
      assert!(direct.contains("<rect"), "the direct form shades: {direct}");
      assert_eq!(indirect, direct, "the indirect form must shade the same");
      // The same for the other two-variable field plots.
      assert_eq!(
        export_svg("q = x + y; ContourPlot[q, {x, -2, 2}, {y, -2, 2}]"),
        export_svg("ContourPlot[x + y, {x, -2, 2}, {y, -2, 2}]")
      );
      assert_eq!(
        export_svg("r = x y; DensityPlot[r, {x, -2, 2}, {y, -2, 2}]"),
        export_svg("DensityPlot[x y, {x, -2, 2}, {y, -2, 2}]")
      );
      // A body that already mentions both variables is untouched, and one
      // that never gains them stays unplottable rather than erroring.
      assert!(
        export_svg("RegionPlot[z > 0, {x, -1, 1}, {y, -1, 1}]")
          .starts_with("<svg")
      );
    }

    /// Field plots draw their own axes, so `PlotLabel` needs its own pass —
    /// it used to be ignored entirely. A size on the outermost `Style` is the
    /// label's font size and must be applied at render resolution.
    #[test]
    fn field_plot_draws_its_plot_label() {
      let svg = export_svg(
        r#"RegionPlot[y > x, {x, -2, 2}, {y, -2, 2}, PlotLabel -> "HELLO"]"#,
      );
      assert!(svg.contains(">HELLO"), "{svg}");
      // Styled and structured labels render their content, not their source.
      let styled = export_svg(
        r#"RegionPlot[y > x, {x, -2, 2}, {y, -2, 2}, PlotLabel -> Style[Row[{"a", " > ", "b"}], 20]]"#,
      );
      assert!(styled.contains("a &gt; b"), "{styled}");
      // The `Style` size lands on the text element at 10x render scale, not
      // as a bare `font-size="20"` that would draw ten times too small.
      assert!(styled.contains("font-size=\"200\""), "{styled}");
    }

