mod edge_list {
  use super::*;

  #[test]
  fn basic_directed_graph() {
    assert_eq!(
      interpret("EdgeList[Graph[{1 -> 2, 2 -> 3}]]").unwrap(),
      "{1  2, 2  3}"
    );
  }

  #[test]
  fn single_edge() {
    assert_eq!(interpret("EdgeList[Graph[{1 -> 2}]]").unwrap(), "{1  2}");
  }

  #[test]
  fn triangle_graph() {
    assert_eq!(
      interpret("EdgeList[Graph[{1 -> 2, 2 -> 3, 3 -> 1}]]").unwrap(),
      "{1  2, 2  3, 3  1}"
    );
  }

  #[test]
  fn unevaluated_for_non_graph() {
    assert_eq!(interpret("EdgeList[5]").unwrap(), "EdgeList[5]");
  }

  #[test]
  fn unevaluated_no_args() {
    assert_eq!(interpret("EdgeList[]").unwrap(), "EdgeList[]");
  }

  #[test]
  fn from_explicit_graph() {
    assert_eq!(
      interpret("EdgeList[Graph[{1, 2, 3}, {1  2, 2  3}]]").unwrap(),
      "{1  2, 2  3}"
    );
  }

  #[test]
  fn directed_edge_infix_syntax() {
    // \[DirectedEdge] infix operator should parse as a  b
    assert_eq!(interpret("1 \\[DirectedEdge] 2").unwrap(), "1  2");
  }

  #[test]
  fn undirected_edge_infix_syntax() {
    // \[UndirectedEdge] infix operator should parse as a  b
    assert_eq!(interpret("1 \\[UndirectedEdge] 2").unwrap(), "1  2");
  }

  #[test]
  fn directed_edge_infix_in_list() {
    assert_eq!(
      interpret("{1 \\[DirectedEdge] 2, 3 \\[DirectedEdge] 4}").unwrap(),
      "{1  2, 3  4}"
    );
  }

  #[test]
  fn graph_from_directed_edge_infix() {
    assert_eq!(
      interpret(
        "EdgeList[Graph[{1 \\[DirectedEdge] 2, 2 \\[DirectedEdge] 3}]]"
      )
      .unwrap(),
      "{1  2, 2  3}"
    );
  }
}

