mod find_graph_isomorphism {
  use super::*;

  #[test]
  fn simple_path() {
    assert_eq!(
      interpret(
        "FindGraphIsomorphism[Graph[{1, 2, 3}, {1 -> 2, 2 -> 3}], Graph[{a, b, c}, {a -> b, b -> c}]]"
      )
      .unwrap(),
      "{<|1 -> a, 2 -> b, 3 -> c|>}"
    );
  }

  #[test]
  fn non_isomorphic_different_sizes() {
    assert_eq!(
      interpret(
        "FindGraphIsomorphism[Graph[{1, 2}, {1 -> 2}], Graph[{a, b, c}, {a -> b, b -> c}]]"
      )
      .unwrap(),
      "{}"
    );
  }

  #[test]
  fn triangle_graph() {
    assert_eq!(
      interpret(
        "FindGraphIsomorphism[Graph[{1, 2, 3}, {1 -> 2, 2 -> 3, 1 -> 3}], Graph[{a, b, c}, {a -> b, b -> c, a -> c}]]"
      )
      .unwrap(),
      "{<|1 -> a, 2 -> b, 3 -> c|>}"
    );
  }

  #[test]
  fn all_isomorphisms_directed_triangle() {
    // Directed K3 has exactly 1 isomorphism (not 6, unlike undirected)
    let result = interpret(
      "Length[FindGraphIsomorphism[Graph[{1, 2, 3}, {1 -> 2, 2 -> 3, 1 -> 3}], Graph[{a, b, c}, {a -> b, b -> c, a -> c}], All]]"
    )
    .unwrap();
    assert_eq!(result, "1");
  }

  #[test]
  fn all_isomorphisms_undirected_triangle() {
    // Undirected K3 has 3! = 6 automorphisms
    let result = interpret(
      "Length[FindGraphIsomorphism[Graph[{1, 2, 3}, {1  2, 2  3, 1  3}], Graph[{a, b, c}, {a  b, b  c, a  c}], All]]"
    )
    .unwrap();
    assert_eq!(result, "6");
  }

  #[test]
  fn non_isomorphic_same_size() {
    // 4-vertex path vs 4-vertex star (different degree sequences)
    assert_eq!(
      interpret(
        "FindGraphIsomorphism[Graph[{1, 2, 3, 4}, {1 -> 2, 2 -> 3, 3 -> 4}], Graph[{a, b, c, d}, {a -> b, a -> c, a -> d}]]"
      )
      .unwrap(),
      "{}"
    );
  }

  #[test]
  fn single_edge() {
    assert_eq!(
      interpret(
        "FindGraphIsomorphism[Graph[{1, 2}, {1 -> 2}], Graph[{x, y}, {x -> y}]]"
      )
      .unwrap(),
      "{<|1 -> x, 2 -> y|>}"
    );
  }
}

mod find_spanning_tree {
  use super::*;

  #[test]
  fn triangle() {
    assert_eq!(
      interpret(
        "EdgeList[FindSpanningTree[Graph[{1, 2, 3}, {1  2, 2  3, 1  3}]]]"
      )
      .unwrap(),
      "{1  2, 2  3}"
    );
  }

  #[test]
  fn four_vertices() {
    // A spanning tree of 4 vertices has exactly 3 edges
    assert_eq!(
      interpret(
        "Length[EdgeList[FindSpanningTree[Graph[{1, 2, 3, 4}, {1  2, 2  3, 3  4, 1  4, 1  3}]]]]"
      )
      .unwrap(),
      "3"
    );
  }

  #[test]
  fn tree_edge_count() {
    let result = interpret(
      "Length[EdgeList[FindSpanningTree[Graph[{1, 2, 3, 4, 5}, {1  2, 2  3, 3  4, 4  5, 1  5, 2  4}]]]]"
    )
    .unwrap();
    assert_eq!(result, "4"); // 5 vertices -> 4 edges
  }

  #[test]
  fn already_tree() {
    assert_eq!(
      interpret("EdgeList[FindSpanningTree[Graph[{1, 2, 3}, {1  2, 2  3}]]]")
        .unwrap(),
      "{1  2, 2  3}"
    );
  }
}

