  #[test]
  fn spec_discrete_from_expression() {
    // `{g, PolyhedronData[All]}` and the `Complement`-derived list are not
    // literal lists; they are evaluated to populate the pick lists.
    let expr = interpret_to_expr(POLYHEDRON_EXAMPLE).unwrap();
    let spec = extract_manipulate_spec(&expr).expect("well-formed manipulate");
    assert_eq!(spec.controls.len(), 2);
    match &spec.controls[0] {
      ManipulateControl::Discrete { name, values, .. } => {
        assert_eq!(name, "g");
        // The five Platonic solids, plus the Archimedean solids and
        // their duals with icosahedral symmetry.
        assert_eq!(values.len(), 15, "every known solid");
        assert!(values.contains(&"\"Cube\"".to_string()));
        assert!(values.contains(&"\"TruncatedIcosahedron\"".to_string()));
      }
      _ => panic!("expected discrete control for g"),
    }
    match &spec.controls[1] {
      ManipulateControl::Discrete { name, values, .. } => {
        assert_eq!(name, "p");
        assert!(values.contains(&"\"Volume\"".to_string()));
        // Class names are removed by the `Complement`.
        assert!(!values.contains(&"\"Platonic\"".to_string()));
      }
      _ => panic!("expected discrete control for p"),
    }
  }

