  #[test]
  fn spec_hidden_control_and_extra_display() {
    // `ControlType -> None` makes `data` a mutable *state* variable (a
    // concrete matrix, evaluated once so it doesn't re-randomize), `h`/`w`
    // are sliders, and the trailing `Dynamic[Panel[…]]` is captured as a
    // renderable display element (the checkbox grid).
    let expr = interpret_to_expr(ARRAYPLOT_EXAMPLE).unwrap();
    let spec = extract_manipulate_spec(&expr).expect("well-formed manipulate");
    assert_eq!(spec.controls.len(), 2, "only h/w are visible controls");
    assert!(matches!(
      &spec.controls[0],
      ManipulateControl::Continuous { name, .. } if name == "h"
    ));
    assert!(matches!(
      &spec.controls[1],
      ManipulateControl::Continuous { name, .. } if name == "w"
    ));
    // `data` is live mutable state, not baked into the body.
    assert_eq!(spec.state.len(), 1, "data is the one state variable");
    assert_eq!(spec.state[0].0, "data");
    assert!(
      spec.state[0].1.starts_with("{{"),
      "data should be a concrete matrix: {}",
      spec.state[0].1
    );
    assert!(
      !spec.state[0].1.contains("RandomInteger"),
      "the random matrix must be evaluated once, not left symbolic"
    );
    assert_eq!(spec.body_code, "ArrayPlot[Take[data, h, w]]");
    // The Dynamic checkbox panel is captured as a display element.
    assert_eq!(spec.displays.len(), 1, "one trailing display element");
    assert!(spec.displays[0].contains("Checkbox"));
  }

  #[test]
  fn display_renders_interactive_checkbox_grid() {
    // The trailing `Dynamic[Panel[Grid[Outer[Checkbox[…]]]]]` renders into a
    // widget tree: a panel wrapping a grid of checkboxes, each carrying its
    // `data[[i, j]]` write-back target and current on/off state.
    use woxi::functions::graphics::{
      manipulate_initial_bindings, render_manipulate_display,
    };
    let expr = interpret_to_expr(ARRAYPLOT_EXAMPLE).unwrap();
    let spec = extract_manipulate_spec(&expr).unwrap();
    let bindings = manipulate_initial_bindings(&spec);
    let tree = render_manipulate_display(&spec.displays[0], &bindings);
    assert!(tree.contains(r#""kind":"panel""#), "tree: {tree}");
    assert!(tree.contains(r#""kind":"grid""#), "tree: {tree}");
    assert!(tree.contains(r#""kind":"checkbox""#), "tree: {tree}");
    // A checkbox targets a concrete cell of `data` with 0/1 write-back.
    assert!(
      tree.contains(r#""target":"data[[1,1]]""#),
      "checkbox should bind data[[1,1]]: {tree}"
    );
    assert!(tree.contains(r#""on":"1""#) && tree.contains(r#""off":"0""#));
    // The grid is h×w = 5×5 with the initial slider values.
    let cells = tree.matches(r#""kind":"checkbox""#).count();
    assert_eq!(cells, 25, "5x5 grid of checkboxes");
  }

  #[test]
  fn display_checkbox_reflects_and_mutates_state() {
    // A checkbox's `checked` flag reflects the current `data` cell, and
    // applying a toggle mutation rewrites that cell in the state binding.
    use woxi::functions::graphics::{
      apply_manipulate_mutations, render_manipulate_display,
    };
    // Fixed 2x2 data so the assertion is deterministic: cell (1,1)=1.
    let code = "Manipulate[ArrayPlot[data], \
      {{data, {{1, 0}, {0, 1}}}, ControlType -> None}, \
      Dynamic[Panel[Grid[Outer[Checkbox[Dynamic[data[[#1, #2]]], {0, 1}] &, \
      Range[2], Range[2]]]]]]";
    let expr = interpret_to_expr(code).unwrap();
    let spec = extract_manipulate_spec(&expr).unwrap();
    let mut bindings =
      vec![("data".to_string(), "{{1, 0}, {0, 1}}".to_string())];
    let tree = render_manipulate_display(&spec.displays[0], &bindings);
    // data[[1,1]] = 1 -> checked; data[[1,2]] = 0 -> unchecked.
    let i11 = tree.find(r#""target":"data[[1,1]]""#).unwrap();
    assert!(tree[i11..i11 + 80].contains(r#""checked":true"#));
    let i12 = tree.find(r#""target":"data[[1,2]]""#).unwrap();
    assert!(tree[i12..i12 + 80].contains(r#""checked":false"#));

    // Toggle cell (1,2) on: the state value of `data` updates.
    let updated =
      apply_manipulate_mutations(&bindings, &["data[[1,2]] = 1".to_string()]);
    assert_eq!(updated.len(), 1);
    assert_eq!(updated[0].0, "data");
    assert_eq!(updated[0].1, "{{1, 1}, {0, 1}}");

    // Re-render with the mutated state: cell (1,2) is now checked.
    bindings[0].1 = updated[0].1.clone();
    let tree2 = render_manipulate_display(&spec.displays[0], &bindings);
    let j12 = tree2.find(r#""target":"data[[1,2]]""#).unwrap();
    assert!(tree2[j12..j12 + 80].contains(r#""checked":true"#));
  }

