  #[test]
  fn abs_1() {
    assert_case(
      r#"Abs[-3]; Plot[Abs[x], {x, -4, 4}]; Abs[3 + I]"#,
      r#"Sqrt[10]"#,
    );
  }
  #[test]
  fn abs_2() {
    assert_case(
      r#"Abs[-3]; Plot[Abs[x], {x, -4, 4}]; Abs[3 + I]; Abs[3.0 + I]"#,
      r#"3.1622776601683795"#,
    );
  }
  #[test]
  fn abs_3() {
    assert_case(
      r#"Abs[-3]; Plot[Abs[x], {x, -4, 4}]; Abs[3 + I]; Abs[3.0 + I]; Abs[Infinity] == Abs[I Infinity] == Abs[ComplexInfinity]"#,
      r#"True"#,
    );
  }
