  #[test]
  fn piecewise() {
    assert_case(
      r#"Piecewise[{{0, x <= 0}}, 1]; Integrate[Piecewise[{{1, x <= 0}, {-1, x > 0}}], x]; Integrate[Piecewise[{{1, x <= 0}, {-1, x > 0}}], {x, -1, 2}]; Piecewise[{{1, False}}]; Plot[Piecewise[{{Log[x], x > 0}, {x*-0.5, x < 0}}], {x, -1, 1}]; Piecewise[{{0 ^ 0, False}}, -1]"#,
      r#"-1"#,
    );
  }
