  #[test]
  fn graphics_28() {
    assert_case(
      r#"Plot[Sin[Cos[x^2]],{x,-4,4}, PlotRange -> All]; Graphics[Disk[], PlotRange -> {{-.5, .5}, {0, 1.5}}]"#,
      r#"Graphics[Disk[{0, 0}], PlotRange -> {{-0.5, 0.5}, {0, 1.5}}]"#,
    );
  }
