  #[test]
  fn limit_1() {
    assert_case(
      r#"Limit[x, x->2]; Limit[Sin[x] / x, x->0]; Plot[1/x, {x, -10, +10}]; Limit[1/x, x->0, Direction->-1]"#,
      r#"Infinity"#,
    );
  }
  #[test]
  fn limit_2() {
    assert_case(
      r#"Limit[x, x->2]; Limit[Sin[x] / x, x->0]; Plot[1/x, {x, -10, +10}]; Limit[1/x, x->0, Direction->-1]; Limit[1/x, x->0, Direction->1]"#,
      r#"-Infinity"#,
    );
  }
  #[test]
  fn limit_3() {
    assert_case(
      r#"Limit[x, x->2]; Limit[Sin[x] / x, x->0]; Plot[1/x, {x, -10, +10}]; Limit[1/x, x->0, Direction->-1]; Limit[1/x, x->0, Direction->1]; Limit[Tan[x], x->Infinity]"#,
      r#"Indeterminate"#,
    );
  }
