  #[test]
  fn output_form() {
    // OutputForm now keeps its wrapper so wolframscript matches —
    // `OutputForm[Graphics[Rectangle[]]]` prints as
    // `OutputForm[-Graphics-]` rather than the bare abbreviation.
    assert_case(
      r#"OutputForm[f'[x]]; OutputForm[Derivative[1, 0][f][x]]; OutputForm[{"A string", a + b}]; {"A string", a + b}; OutputForm[Graphics[Rectangle[]]]"#,
      r#"OutputForm[-Graphics-]"#,
    );
  }
