  #[test]
  fn graphics_31() {
    assert_case(
      r#"Cross[{x1, y1, z1}, {x2, y2, z2}]; Cross[{x, y}]; v1 = {1, Sqrt[3]}; v2 = Cross[v1]; Graphics[{Arrow[{{0, 0}, v1}], Red, Arrow[{{0, 0}, v2}]}, Axes -> True]"#,
      r#"Graphics[{Arrow[{{0, 0}, {1, Sqrt[3]}}], RGBColor[1, 0, 0], Arrow[{{0, 0}, {-Sqrt[3], 1}}]}, Axes -> True]"#,
    );
  }
  #[test]
  fn plus() {
    assert_case(
      r#"1 + 2; a + b + a; a + a + 3 * a; a + b + 4.5 + a + b + a + 2 + 1.5 b; Plus @@ {2, 4, 6}; Plus @@ Range[1000]; DefaultValues[Plus]; a /. n_. + x_ :> {n, x}; 2 Graphics[{Red,Disk[]}] + 3 Graphics[{Red,Disk[]}]"#,
      r#"5*Graphics[{RGBColor[1, 0, 0], Disk[{0, 0}]}]"#,
    );
  }
  #[test]
  fn black() {
    assert_case(r#"Black"#, r#"GrayLevel[0]"#);
  }
  #[test]
  fn blue() {
    assert_case(r#"Blue"#, r#"RGBColor[0, 0, 1]"#);
  }
  #[test]
  fn brown() {
    assert_case(r#"Brown"#, r#"RGBColor[0.6, 0.4, 0.2]"#);
  }
  #[test]
  fn cyan() {
    assert_case(r#"Cyan"#, r#"RGBColor[0, 1, 1]"#);
  }
  #[test]
  fn gray() {
    assert_case(r#"Gray"#, r#"GrayLevel[0.5]"#);
  }
  #[test]
  fn green() {
    assert_case(r#"Green"#, r#"RGBColor[0, 1, 0]"#);
  }
  #[test]
  fn magenta() {
    assert_case(r#"Magenta"#, r#"RGBColor[1, 0, 1]"#);
  }
  #[test]
  fn graphics_32() {
    assert_case(
      r#"Graphics[{LightBlue, EdgeForm[Black], Disk[]}]"#,
      r#"Graphics[{RGBColor[0.87, 0.94, 1], EdgeForm[GrayLevel[0]], Disk[{0, 0}]}]"#,
    );
  }
