  #[test]
  fn red() {
    assert_case(r#"Red"#, r#"RGBColor[1, 0, 0]"#);
  }
  #[test]
  fn yellow() {
    assert_case(r#"Yellow"#, r#"RGBColor[1, 1, 0]"#);
  }
  #[test]
  fn white() {
    assert_case(r#"White"#, r#"GrayLevel[1]"#);
  }
  #[test]
  fn graphics_33() {
    assert_case(
      r#"Graphics[MapIndexed[{CMYKColor @@ #1, Disk[2*#2 ~Join~ {0}]} &, IdentityMatrix[4]], ImageSize->Small]"#,
      r#"Graphics[{{CMYKColor[1, 0, 0, 0], Disk[{2, 0}]}, {CMYKColor[0, 1, 0, 0], Disk[{4, 0}]}, {CMYKColor[0, 0, 1, 0], Disk[{6, 0}]}, {CMYKColor[0, 0, 0, 1], Disk[{8, 0}]}}, ImageSize -> Small]"#,
    );
  }
  #[test]
  fn color_distance_1() {
    assert_case(r#"ColorDistance[Magenta, Green]"#, r#"2.250666704346899"#);
  }
  #[test]
  fn color_distance_2() {
    assert_case(
      r#"ColorDistance[Magenta, Green]; ColorDistance[{Red, Blue}, {Green, Yellow}, DistanceFunction -> {"CMC", "Perceptibility"}]"#,
      r#"{1.0494615540506513, 1.2745445575741197}"#,
    );
  }
