  #[test]
  fn hypergeometric1_f1_1() {
    assert_case(
      r#"Hypergeometric1F1[1, 2, 3.0]; Plot[Hypergeometric1F1[1, 2, x], {x, -5, 5}]; Plot[{Hypergeometric1F1[1/2, Sqrt[2], x], Hypergeometric1F1[1/2, Sqrt[3], x], Hypergeometric1F1[1/2, Sqrt[5], x]}, {x, -4, 4}]; Plot[{Hypergeometric1F1[Sqrt[3], Sqrt[2], z], -0.01}, {z, -10, -2}]; Plot[{Hypergeometric1F1[Sqrt[2], b, 1], Hypergeometric1F1[Sqrt[5], b, 1], Hypergeometric1F1[Sqrt[7], b, 1]}, {b, -3, 3}]; Hypergeometric1F1[1, 1, {{1, 0}, {0, 1}}]"#,
      r#"{{E, 1}, {1, E}}"#,
    );
  }
