  #[test]
  fn hypergeometric_pfq_1() {
    assert_case(
      r#"HypergeometricPFQ[{2}, {2}, 1]; HypergeometricPFQ[{3}, {2}, 1]; HypergeometricPFQ[{3}, {2}, 1] // N; HypergeometricPFQ[{3}, {2}, 1.]; Plot[HypergeometricPFQ[{1, 1}, {3, 3, 3}, x], {x, -30, 30}]; HypergeometricPFQ[{1, 1, 2}, {3, 3}, z]"#,
      r#"(-4*(-2*z - Log[1 - z] + z*Log[1 - z] + PolyLog[2, z]))/z^2"#,
    );
  }
  #[test]
  fn hypergeometric_pfq_2() {
    assert_case(
      r#"HypergeometricPFQ[{2}, {2}, 1]; HypergeometricPFQ[{3}, {2}, 1]; HypergeometricPFQ[{3}, {2}, 1] // N; HypergeometricPFQ[{3}, {2}, 1.]; Plot[HypergeometricPFQ[{1, 1}, {3, 3, 3}, x], {x, -30, 30}]; HypergeometricPFQ[{1, 1, 2}, {3, 3}, z]; HypergeometricPFQ[{}, {}, z]"#,
      r#"E ^ z"#,
    );
  }
  #[test]
  fn hypergeometric_pfq_3() {
    assert_case(
      r#"HypergeometricPFQ[{2}, {2}, 1]; HypergeometricPFQ[{3}, {2}, 1]; HypergeometricPFQ[{3}, {2}, 1] // N; HypergeometricPFQ[{3}, {2}, 1.]; Plot[HypergeometricPFQ[{1, 1}, {3, 3, 3}, x], {x, -30, 30}]; HypergeometricPFQ[{1, 1, 2}, {3, 3}, z]; HypergeometricPFQ[{}, {}, z]; HypergeometricPFQ[{0}, {b}, z]"#,
      r#"1"#,
    );
  }
  #[test]
  fn hypergeometric_pfq_4() {
    assert_case(
      r#"HypergeometricPFQ[{2}, {2}, 1]; HypergeometricPFQ[{3}, {2}, 1]; HypergeometricPFQ[{3}, {2}, 1] // N; HypergeometricPFQ[{3}, {2}, 1.]; Plot[HypergeometricPFQ[{1, 1}, {3, 3, 3}, x], {x, -30, 30}]; HypergeometricPFQ[{1, 1, 2}, {3, 3}, z]; HypergeometricPFQ[{}, {}, z]; HypergeometricPFQ[{0}, {b}, z]; HypergeometricPFQ[{1, 1, 3}, {2, 2}, x]"#,
      r#"(-x + Log[1 - x] - x*Log[1 - x])/(2*(-1 + x)*x)"#,
    );
  }
  #[test]
  fn hypergeometric_pfq_5() {
    assert_case(
      r#"HypergeometricPFQ[{2}, {2}, 1]; HypergeometricPFQ[{3}, {2}, 1]; HypergeometricPFQ[{3}, {2}, 1] // N; HypergeometricPFQ[{3}, {2}, 1.]; Plot[HypergeometricPFQ[{1, 1}, {3, 3, 3}, x], {x, -30, 30}]; HypergeometricPFQ[{1, 1, 2}, {3, 3}, z]; HypergeometricPFQ[{}, {}, z]; HypergeometricPFQ[{0}, {b}, z]; HypergeometricPFQ[{1, 1, 3}, {2, 2}, x]; HypergeometricPFQ[{-2, a}, {b}, x]"#,
      r#"1 - (2*a*x)/b - ((-1 - a)*a*x^2)/(b*(1 + b))"#,
    );
  }
  #[test]
  fn hypergeometric_pfq_6() {
    assert_case(
      r#"HypergeometricPFQ[{2}, {2}, 1]; HypergeometricPFQ[{3}, {2}, 1]; HypergeometricPFQ[{3}, {2}, 1] // N; HypergeometricPFQ[{3}, {2}, 1.]; Plot[HypergeometricPFQ[{1, 1}, {3, 3, 3}, x], {x, -30, 30}]; HypergeometricPFQ[{1, 1, 2}, {3, 3}, z]; HypergeometricPFQ[{}, {}, z]; HypergeometricPFQ[{0}, {b}, z]; HypergeometricPFQ[{1, 1, 3}, {2, 2}, x]; HypergeometricPFQ[{-2, a}, {b}, x]; HypergeometricPFQ[{a1, b2, a3}, {b1, b2, b3}, 0]"#,
      r#"1"#,
    );
  }
