  #[test]
  fn bessel_i_1() {
    assert_case(
      r#"BesselI[0, 0]; BesselI[1.5, 4]; Plot[BesselI[0, x], {x, 0, 5}]; BesselI[3/2, x]"#,
      r#"(2*Cosh[x] - (2*Sinh[x])/x)/(Sqrt[2*Pi]*Sqrt[x])"#,
    );
  }
  #[test]
  fn bessel_i_2() {
    assert_case(
      r#"BesselI[0, 0]; BesselI[1.5, 4]; Plot[BesselI[0, x], {x, 0, 5}]; BesselI[3/2, x]; BesselI[1, z]"#,
      r#"BesselI[1, z]"#,
    );
  }
