  #[test]
  fn bessel_j_1() {
    assert_case(
      r#"BesselJ[0, 5.2]; D[BesselJ[n, z], z]; BesselJ[0., 0.]; Plot[BesselJ[0, x], {x, 0, 10}]; BesselJ[1/2, x]"#,
      r#"(Sqrt[2/Pi]*Sin[x])/Sqrt[x]"#,
    );
  }
  #[test]
  fn bessel_j_2() {
    assert_case(
      r#"BesselJ[0, 5.2]; D[BesselJ[n, z], z]; BesselJ[0., 0.]; Plot[BesselJ[0, x], {x, 0, 10}]; BesselJ[1/2, x]; BesselJ[2, z]"#,
      r#"BesselJ[2, z]"#,
    );
  }
  #[test]
  fn integrate() {
    assert_case(
      r#"BesselJ[0, 5.2]; D[BesselJ[n, z], z]; BesselJ[0., 0.]; Plot[BesselJ[0, x], {x, 0, 10}]; BesselJ[1/2, x]; BesselJ[2, z]; Integrate[Cos[3 Sin[w]], {w, 0, Pi}]"#,
      r#"Pi*BesselJ[0, 3]"#,
    );
  }
