  #[test]
  fn bessel_k_1() {
    assert_case(
      r#"BesselK[1.5, 4]; Plot[BesselK[0, x], {x, 0, 5}]; BesselK[-3/2, x]"#,
      r#"(Sqrt[Pi/2]*(1 + x^(-1)))/(E^x*Sqrt[x])"#,
    );
  }
  #[test]
  fn bessel_k_2() {
    assert_case(
      r#"BesselK[1.5, 4]; Plot[BesselK[0, x], {x, 0, 5}]; BesselK[-3/2, x]; BesselK[1, z]"#,
      r#"BesselK[1, z]"#,
    );
  }
