  #[test]
  fn bessel_y_1() {
    assert_case(
      r#"BesselY[1.5, 4]; BesselY[0., 0.]; Plot[BesselY[0, x], {x, 0, 10}]; BesselY[-3/2, x]"#,
      r#"(Sqrt[2/Pi]*(Cos[x] - Sin[x]/x))/Sqrt[x]"#,
    );
  }
  #[test]
  fn bessel_y_2() {
    assert_case(
      r#"BesselY[1.5, 4]; BesselY[0., 0.]; Plot[BesselY[0, x], {x, 0, 10}]; BesselY[-3/2, x]; BesselY[1, z]"#,
      r#"BesselY[1, z]"#,
    );
  }
  #[test]
  fn bessel_y_3() {
    assert_case(
      r#"BesselY[1.5, 4]; BesselY[0., 0.]; Plot[BesselY[0, x], {x, 0, 10}]; BesselY[-3/2, x]; BesselY[1, z]; BesselY[0, 0]"#,
      r#"-Infinity"#,
    );
  }
